async fn get_terminal_preferences(
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<crate::terminal::TerminalPreferences>, (StatusCode, String)> {
    let _token = extract_token(&headers, Some(&query)).ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    Ok(Json(crate::terminal::load_terminal_preferences()))
}

pub fn create_remote_router(state: Arc<RemoteGatewayState>) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    Router::new()
        .route("/api/v1/health", get(health_check))
        .route("/api/v1/pair/exchange", post(pair_exchange))
        .route("/api/v1/sessions", get(list_sessions))
        .route("/api/v1/workspace/state", get(get_workspace_state))
        .route("/api/v1/terminal/preferences", get(get_terminal_preferences))
        .route("/api/v1/workspace/worktrees", post(create_worktree).delete(delete_worktree))
        .route("/api/v1/devices", get(list_devices))
        .route("/api/v1/devices/{id}/revoke", post(revoke_device))
        .route("/api/v1/events", get(ws_events_handler))
        .route("/api/v1/terminal/{sessionId}", get(ws_terminal_handler))
        .fallback(get(serve_static_or_index))
        .layer(cors)
        .with_state(state)
}

pub struct RemoteServerHandle {
    shutdown_tx: tokio::sync::oneshot::Sender<()>,
}

impl RemoteServerHandle {
    pub fn stop(self) {
        let _ = self.shutdown_tx.send(());
    }
}

pub async fn start_remote_server(
    state: Arc<RemoteGatewayState>,
) -> Result<(RemoteServerHandle, SocketAddr), String> {
    let config = state.config.read().clone();
    let bind_host = match config.mode {
        RemoteNetworkMode::Off => return Err("Remote gateway is OFF".into()),
        _ => "0.0.0.0",
    };

    let bind_addr: SocketAddr = format!("{bind_host}:{}", config.port)
        .parse()
        .map_err(|e| format!("Invalid bind address: {e}"))?;

    let listener = tokio::net::TcpListener::bind(bind_addr)
        .await
        .map_err(|e| format!("Failed to bind to {bind_addr}: {e}"))?;

    let local_addr = listener
        .local_addr()
        .map_err(|e| format!("Failed to get local address: {e}"))?;

    let router = create_remote_router(Arc::clone(&state));
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel::<()>();

    *state.is_running.write() = true;
    *state.bound_address.write() = Some(local_addr.to_string());

    let state_clone = Arc::clone(&state);
    tokio::spawn(async move {
        axum::serve(listener, router)
            .with_graceful_shutdown(async move {
                let _ = shutdown_rx.await;
            })
            .await
            .ok();

        *state_clone.is_running.write() = false;
        *state_clone.bound_address.write() = None;
    });

    Ok((RemoteServerHandle { shutdown_tx }, local_addr))
}

use crate::remote::auth::{write_private_json, AuthManager};
use crate::terminal::TerminalService;
use crate::worktree::WorkspaceRegistry;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum RemoteNetworkMode {
    Off,
    LocalNetwork,
    Tailscale,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RemoteGatewayConfig {
    pub mode: RemoteNetworkMode,
    pub port: u16,
    pub allow_control: bool,
}

impl Default for RemoteGatewayConfig {
    fn default() -> Self {
        Self {
            mode: RemoteNetworkMode::Off,
            port: 43821,
            allow_control: true,
        }
    }
}

pub struct RemoteGatewayState {
    pub config: RwLock<RemoteGatewayConfig>,
    pub auth_manager: Arc<AuthManager>,
    pub terminal_service: Arc<TerminalService>,
    pub workspace_registry: WorkspaceRegistry,
    pub event_tx: broadcast::Sender<String>,
    pub is_running: RwLock<bool>,
    pub bound_address: RwLock<Option<String>>,
    config_path: Option<PathBuf>,
}

impl RemoteGatewayState {
    pub fn new(terminal_service: Arc<TerminalService>, workspace_registry: WorkspaceRegistry) -> Self {
        Self::new_with_paths(terminal_service, workspace_registry, None, None)
    }

    pub fn new_persistent(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
    ) -> Self {
        let base = remote_data_dir();
        Self::new_with_paths(
            terminal_service,
            workspace_registry,
            Some(base.join("remote-config.json")),
            Some(base.join("remote-auth.json")),
        )
    }

    pub fn new_with_paths(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
        config_path: Option<PathBuf>,
        auth_path: Option<PathBuf>,
    ) -> Self {
        let (event_tx, _) = broadcast::channel(1024);
        let config = config_path
            .as_deref()
            .and_then(|path| std::fs::read(path).ok())
            .and_then(|bytes| serde_json::from_slice::<RemoteGatewayConfig>(&bytes).ok())
            .unwrap_or_default();
        Self {
            config: RwLock::new(config),
            auth_manager: Arc::new(AuthManager::with_persistence(auth_path)),
            terminal_service,
            workspace_registry,
            event_tx,
            is_running: RwLock::new(false),
            bound_address: RwLock::new(None),
            config_path,
        }
    }

    pub fn emit_event(&self, event_json: String) {
        let _ = self.event_tx.send(event_json);
    }

    pub fn persist_config(&self) -> std::io::Result<()> {
        let Some(path) = self.config_path.as_deref() else {
            return Ok(());
        };
        write_private_json(path, &*self.config.read())
    }
}

fn remote_data_dir() -> PathBuf {
    if let Some(path) = std::env::var_os("FERRYX_DATA_DIR") {
        return PathBuf::from(path).join("remote");
    }
    if let Some(home) = std::env::var_os("HOME") {
        return PathBuf::from(home).join(".ferryx").join("remote");
    }
    std::env::temp_dir().join("ferryx").join("remote")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::terminal::{PtyManager, TerminalOutputHub};

    #[test]
    fn gateway_config_survives_reopen() {
        let dir = tempfile::TempDir::new().expect("tempdir");
        let config_path = dir.path().join("config.json");
        let auth_path = dir.path().join("auth.json");
        let pty = Arc::new(PtyManager::new());
        let hub = Arc::new(TerminalOutputHub::default());
        let terminal = Arc::new(TerminalService::new(pty, hub));
        let registry = WorkspaceRegistry::new();
        let state = RemoteGatewayState::new_with_paths(
            Arc::clone(&terminal),
            registry.clone(),
            Some(config_path.clone()),
            Some(auth_path.clone()),
        );
        state.config.write().mode = RemoteNetworkMode::LocalNetwork;
        state.config.write().port = 45678;
        state.persist_config().expect("persist");

        let reopened = RemoteGatewayState::new_with_paths(
            terminal,
            registry,
            Some(config_path),
            Some(auth_path),
        );
        let config = reopened.config.read();
        assert_eq!(config.mode, RemoteNetworkMode::LocalNetwork);
        assert_eq!(config.port, 45678);
    }
}

use super::*;
use crate::terminal::TerminalService;
use std::sync::Arc;

struct MockTailscaleRunner {
    installed: bool,
    running: bool,
    self_dns: Option<String>,
}

impl CommandRunner for MockTailscaleRunner {
    fn run(&self, program: &str, args: &[&str]) -> Result<String, String> {
        if program != "tailscale" {
            return Err("not tailscale".into());
        }
        if !self.installed {
            return Err("command not found".into());
        }
        if args.contains(&"status") {
            let json = serde_json::json!({
                "BackendState": if self.running { "Running" } else { "Stopped" },
                "CurrentTailnet": { "Name": "test-tailnet" },
                "Self": { "DNSName": self.self_dns.as_deref().unwrap_or("my-mac.test.ts.net.") }
            });
            Ok(json.to_string())
        } else if args.contains(&"serve") {
            Ok(r#"{"TCP":{"43821":{"HTTPS":true}}}"#.into())
        } else {
            Ok("".into())
        }
    }
}

#[test]
fn test_tailscale_status_parsing() {
    let runner = MockTailscaleRunner {
        installed: true,
        running: true,
        self_dns: Some("my-mac.tailnet.ts.net.".into()),
    };
    let status = check_tailscale_status(&runner);
    assert!(status.installed);
    assert!(status.running);
    assert_eq!(status.self_dns, Some("my-mac.tailnet.ts.net".into()));
    assert_eq!(status.tailnet_name, Some("test-tailnet".into()));
}

#[test]
fn test_auth_manager_pairing_and_revocation() {
    let auth = AuthManager::new();
    let code = auth.create_pairing_code(DevicePermission::Control);

    // Invalid code fails
    assert!(auth.exchange_pairing_code("invalid_code", "test-device").is_err());

    // Valid code succeeds
    let (token, device) = auth.exchange_pairing_code(&code, "test-device").expect("exchange success");
    assert_eq!(device.permission, DevicePermission::Control);
    assert!(!device.revoked);

    // Code is single use
    assert!(auth.exchange_pairing_code(&code, "test-device-2").is_err());

    // Validate token
    let validated = auth.validate_token(&token).expect("validate success");
    assert_eq!(validated.id, device.id);

    // Revoke device
    assert!(auth.revoke_device(&device.id));
    assert!(matches!(auth.validate_token(&token), Err(AuthError::RevokedDevice)));
}

#[tokio::test]
async fn test_remote_server_health_and_lifecycle() {
    let terminal_service = Arc::new(TerminalService::default());
    let state = Arc::new(RemoteGatewayState::new(terminal_service, crate::worktree::WorkspaceRegistry::new()));

    *state.config.write() = RemoteGatewayConfig {
        mode: RemoteNetworkMode::Tailscale,
        port: 0, // OS assigns available port
        allow_control: true,
    };

    let (handle, addr) = start_remote_server(Arc::clone(&state)).await.expect("start server");
    assert!(addr.ip().is_unspecified() || addr.ip().is_loopback());

    // Health endpoint
    let client = reqwest_like_health(&format!("http://{addr}/api/v1/health")).await;
    assert!(client);

    handle.stop();
}

async fn reqwest_like_health(url: &str) -> bool {
    // simple TCP request
    let parsed: std::net::SocketAddr = url.trim_start_matches("http://").trim_end_matches("/api/v1/health").parse().unwrap();
    if let Ok(mut stream) = tokio::net::TcpStream::connect(parsed).await {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let req = b"GET /api/v1/health HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n";
        let _ = stream.write_all(req).await;
        let mut buf = [0u8; 1024];
        if let Ok(n) = stream.read(&mut buf).await {
            let res = String::from_utf8_lossy(&buf[..n]);
            return res.contains("200 OK") && res.contains(r#""status":"ok""#);
        }
    }
    false
}


#[tokio::test]
async fn test_remote_server_serves_spa_index_html() {
    let terminal_service = Arc::new(TerminalService::default());
    let state = Arc::new(RemoteGatewayState::new(terminal_service, crate::worktree::WorkspaceRegistry::new()));

    *state.config.write() = RemoteGatewayConfig {
        mode: RemoteNetworkMode::LocalNetwork,
        port: 0,
        allow_control: true,
    };

    let (handle, addr) = start_remote_server(Arc::clone(&state)).await.expect("start server");

    let parsed: std::net::SocketAddr = addr;
    if let Ok(mut stream) = tokio::net::TcpStream::connect(parsed).await {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let req = b"GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n";
        let _ = stream.write_all(req).await;
        let mut buf = [0u8; 4096];
        if let Ok(n) = stream.read(&mut buf).await {
            let res = String::from_utf8_lossy(&buf[..n]);
            assert!(res.contains("200 OK"));
            assert!(res.contains("<!doctype html>") || res.contains("<html"));
        }
    }

    handle.stop();
}

#[test]
fn test_derive_session_metadata_matches_workspace() {
    let dir = tempfile::TempDir::new().expect("tempdir");
    let repo_root = dir.path().join("repo");
    std::fs::create_dir_all(&repo_root).unwrap();
    crate::worktree::run_git(&repo_root, &["init"]).expect("git init");
    let wt = repo_root.join("wt-a");
    std::fs::create_dir_all(&wt).unwrap();

    let registry = crate::worktree::WorkspaceRegistry::new();
    registry.register("ws1", &repo_root).expect("register");

    // Path inside a registered workspace but not a listed git worktree:
    // workspace matches, label falls back to the path's file name.
    let (ws_id, label) = crate::remote::server::derive_session_metadata(&registry, Some(&wt));
    assert_eq!(ws_id.as_deref(), Some("ws1"));
    assert_eq!(label.as_deref(), Some("wt-a"));

    // Path outside any registered workspace: no workspace id, best-effort label.
    let other = dir.path().join("other");
    std::fs::create_dir_all(&other).unwrap();
    let (ws_id, label) = crate::remote::server::derive_session_metadata(&registry, Some(&other));
    assert_eq!(ws_id, None);
    assert_eq!(label.as_deref(), Some("other"));

    // No owning worktree path at all.
    assert_eq!(
        crate::remote::server::derive_session_metadata(&registry, None),
        (None, None)
    );
}

use crate::worktree::{Worktree, WorktreeError, WorktreeIdentity, WorktreeManager};
use parking_lot::RwLock;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

#[derive(Debug, Clone, Default)]
pub struct WorkspaceRegistry {
    workspaces: Arc<RwLock<HashMap<String, WorktreeManager>>>,
}

impl WorkspaceRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    fn validate_workspace_id(workspace_id: &str) -> Result<&str, WorktreeError> {
        let workspace_id = workspace_id.trim();
        if workspace_id.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace registry ID cannot be empty".into(),
            });
        }
        if workspace_id.starts_with('-')
            || workspace_id.contains('/')
            || workspace_id.contains('\\')
            || workspace_id.chars().any(|ch| ch.is_control() || ch.is_whitespace())
        {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace registry ID contains unsafe characters".into(),
            });
        }
        Ok(workspace_id)
    }

    pub fn register(
        &self,
        workspace_id: impl AsRef<str>,
        repo_root: impl AsRef<Path>,
    ) -> Result<(), WorktreeError> {
        let workspace_id = Self::validate_workspace_id(workspace_id.as_ref())?.to_string();
        let manager = WorktreeManager::try_new(repo_root.as_ref().to_path_buf())?;
        let mut workspaces = self.workspaces.write();
        if let Some(existing) = workspaces.get(&workspace_id) {
            if existing.repo_root() == manager.repo_root() {
                return Ok(());
            }
            return Err(WorktreeError::WorkspaceAlreadyRegistered { workspace_id });
        }
        workspaces.insert(workspace_id, manager);
        Ok(())
    }

    pub fn contains(&self, workspace_id: &str) -> bool {
        self.workspaces.read().contains_key(workspace_id)
    }

    pub fn list(&self) -> Vec<(String, WorktreeManager)> {
        self.workspaces
            .read()
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect()
    }

    pub fn manager(&self, workspace_id: &str) -> Result<WorktreeManager, WorktreeError> {
        let workspace_id = Self::validate_workspace_id(workspace_id)?;
        self.workspaces
            .read()
            .get(workspace_id)
            .cloned()
            .ok_or_else(|| WorktreeError::WorkspaceNotFound {
                workspace_id: workspace_id.to_string(),
            })
    }

    pub fn repo_root(&self, workspace_id: &str) -> Result<PathBuf, WorktreeError> {
        Ok(self.manager(workspace_id)?.repo_root().to_path_buf())
    }

    pub fn target_path(
        &self,
        workspace_id: &str,
        identity: &WorktreeIdentity,
    ) -> Result<PathBuf, WorktreeError> {
        self.manager(workspace_id)?
            .worktree_path_for(&identity.ws_id, &identity.slug)
    }

    pub fn resolve_worktree(
        &self,
        workspace_id: &str,
        identity: &WorktreeIdentity,
    ) -> Result<(WorktreeManager, Worktree), WorktreeError> {
        let manager = self.manager(workspace_id)?;
        let worktree = manager
            .find_worktree_by_slug(&identity.ws_id, &identity.slug)?
            .ok_or_else(|| WorktreeError::WorktreeIdentityNotFound {
                workspace_id: workspace_id.to_string(),
                ws_id: identity.ws_id.clone(),
                slug: identity.slug.clone(),
            })?;
        manager.canonical_allowed_path(&worktree.path)?;
        Ok((manager, worktree))
    }

    pub fn resolve_terminal_target(
        &self,
        workspace_id: &str,
        identity: Option<&WorktreeIdentity>,
    ) -> Result<(WorktreeManager, PathBuf), WorktreeError> {
        if let Some(identity) = identity {
            let (manager, worktree) = self.resolve_worktree(workspace_id, identity)?;
            let path = manager.canonical_allowed_path(&worktree.path)?;
            return Ok((manager, path));
        }

        let manager = self.manager(workspace_id)?;
        let path = manager.repo_root().to_path_buf();
        Ok((manager, path))
    }
}

use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use thiserror::Error;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Worktree {
    pub path: PathBuf,
    pub head: String,
    pub branch: Option<String>,
    pub bare: bool,
    pub detached: bool,
    pub locked: Option<String>,
    pub prunable: Option<String>,
}

impl Worktree {
    /// Returns the short branch name if this worktree is checked out on a branch.
    /// For example, `refs/heads/orca/ws1/feat` -> `orca/ws1/feat`.
    pub fn branch_short_name(&self) -> Option<&str> {
        self.branch
            .as_deref()
            .map(|b| b.strip_prefix("refs/heads/").unwrap_or(b))
    }

    /// Extracts Orca workspace ID and slug if the worktree branch follows `orca/<ws-id>/<slug>`.
    pub fn orca_info(&self) -> Option<OrcaWorktreeInfo> {
        let branch = self.branch_short_name()?;
        let parts: Vec<&str> = branch.split('/').collect();
        if parts.len() >= 3 && parts[0] == "orca" {
            Some(OrcaWorktreeInfo {
                ws_id: parts[1].to_string(),
                slug: parts[2..].join("/"),
            })
        } else {
            None
        }
    }
}

