/// sessions in one request.
pub(crate) fn derive_session_metadata(
    registry: &crate::worktree::WorkspaceRegistry,
    worktree_path: Option<&Path>,
) -> (Option<String>, Option<String>) {
    WorkspaceSnapshotCache::build(registry).derive_session_metadata(worktree_path)
}

fn remote_terminal_session(session: &Arc<crate::terminal::PtySession>, cache: &WorkspaceSnapshotCache) -> RemoteTerminalSession {
    let running = matches!(session.state(), PtySessionState::Running | PtySessionState::Starting);
    let (workspace_id, worktree_label) = cache.derive_session_metadata(session.worktree_path().as_deref());
    RemoteTerminalSession {
        session_id: session.id().to_string(),
        title: None,
        workspace_id,
        worktree_label,
        running,
    }
}

async fn list_sessions(
    State(state): State<Arc<RemoteGatewayState>>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<Vec<RemoteTerminalSession>>, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query)).ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let _device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    let cache = WorkspaceSnapshotCache::build(&state.workspace_registry);
    let sessions = state
        .terminal_service
        .list_sessions()
        .into_iter()
        .filter_map(|id| state.terminal_service.get_session(&id))
        .map(|session| remote_terminal_session(&session, &cache))
        .collect::<Vec<_>>();

    Ok(Json(sessions))
}

